    if (n <= 0 || start == null || end == null || paths == null) {
        throw new IllegalArgumentException("Invalid input");
    }

    HashSet<Integer> visited = new HashSet<>();
    boolean[] isValid = new boolean[n * n];
    for (int[] path : paths) {
        int from = path[0];
        int to = path[1];
        isValid[from] = true;
        isValid[to] = true;
    }

    if (!isValid[start[0] * n + start[1]] || !isValid[end[0] * n + end[1]]) {
        return "cannot be travelled";
    }

    boolean[] directions = new boolean[2];
    directions[0] = true;
    directions[1] = false;

    for (int[] path : paths) {
        int from = path[0];
        int to = path[1];
        int fromRow = from / n;
        int fromCol = from % n;
        int toRow = to / n;
        int toCol = to % n;

        boolean valid = Math.abs(fromRow - toRow) == 1 && Math.abs(fromCol - toCol) == 0 ||
                        Math.abs(fromRow - toRow) == 0 && Math.abs(fromCol - toCol) == 1;

        if (!valid) {
            return "cannot be travelled";
        }

        int[] next = new int[]{toRow, toCol};
        int nextIndex = next[0] * n + next[1];
        if (!visited.contains(nextIndex)) {
            visited.add(nextIndex);
            if (nextIndex == end[0] * n + end[1]) {
