                    possible[i][j] = possible[i - 1][j] || possible[i - 1][j - nums[n - i]];
                } else {
                    possible[i][j] = possible[i - 1][j];
                }
            }
        }
    }

    for (int i = 1; i < n; i++) {
        for (int j = 1; j <= sum; j++) {
            if (possible[i][j] && (sum * i) % n == (sum * (n - i)) % n && j * n == sum * i) {
                return true;
            }
        }
    }

    return false;
}

