public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> steppingNumbers = new ArrayList<>();
        if (low <= 0) {
            steppingNumbers.add(0);
        }
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 1; i <= 9; i++) {
            queue.add(i);
        }

        while (!queue.isEmpty()) {
            int num = queue.poll();
            if (num > high) {
                continue;
            }
            if (num >= low) {
                steppingNumbers.add(num);
            }
            int lastDigit = num % 10;
            if (lastDigit > 0) {
                queue.add(num * 10 + (lastDigit - 1));
            }
            if (lastDigit < 9) {
                queue.add(num * 10 + (lastDigit + 1));
            }
        }

        Collections.sort(steppingNumbers);
        return steppingNumbers;
    }

