public static int minPerfectSquareSum(int n) {
    // Base case
    if (n <= 3) {
        return n;
    }

    // This array will store the minimum number of perfect square numbers
    // that sum up to i. Initialize the array with a large number
    int[] dp = new int[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = i; // Worst case: 1 + 1 + ... + 1 (i times)
    }

    // Iterate through all numbers from 4 to n to fill the dp array
    for (int i = 4; i <= n; i++) {
        // Try every square number smaller than i
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

